changeSet.sql:
-- group versions and stop factors get a sequence each, named after the table it serves
ALTER SEQUENCE stop_factors.stop_factor_id_generator RENAME TO stop_factor_group_id_generator;
ALTER SEQUENCE stop_factors.stop_factor_rule_id_generator RENAME TO stop_factor_id_generator;

-- the metric of a rule is the metric of its stop factor version (all rules of one stop factor share it)
ALTER TABLE stop_factors.stop_factor_group DROP CONSTRAINT fk_stop_factor_metric;
DROP INDEX stop_factors.idx_stop_factor_metric_id;
ALTER TABLE stop_factors.stop_factor_rule ADD COLUMN metric_id BIGINT;
UPDATE stop_factors.stop_factor_rule f
SET metric_id = g.metric_id
FROM stop_factors.stop_factor_group g
WHERE g.id = f.stop_factor_id;
ALTER TABLE stop_factors.stop_factor_rule ALTER COLUMN metric_id SET NOT NULL;
ALTER TABLE stop_factors.stop_factor_rule
    ADD CONSTRAINT fk_stop_factor_metric FOREIGN KEY (metric_id) REFERENCES stop_factors.stop_factor_metric (id);

ALTER TABLE stop_factors.stop_factor_rule RENAME COLUMN stop_factor_id TO group_id;
ALTER TABLE stop_factors.stop_factor_rule RENAME CONSTRAINT fk_stop_factor_rule_stop_factor TO fk_stop_factor_group;
