ALTER TABLE stop_factors.stop_factor_group
    ADD CONSTRAINT fk_stop_factor_metric FOREIGN KEY (metric_id) REFERENCES stop_factors.stop_factor_metric (id);
CREATE INDEX idx_stop_factor_metric_id ON stop_factors.stop_factor_group (metric_id);
ALTER SEQUENCE stop_factors.stop_factor_id_generator RENAME TO stop_factor_rule_id_generator;
ALTER SEQUENCE stop_factors.stop_factor_group_id_generator RENAME TO stop_factor_id_generator;

