ALTER TABLE stop_factors.stop_factor_group ADD COLUMN metric_id BIGINT;
UPDATE stop_factors.stop_factor_group g
SET metric_id = (SELECT f.metric_id FROM stop_factors.stop_factor f
                 WHERE f.group_id = g.id ORDER BY f.order_number LIMIT 1);
ALTER TABLE stop_factors.stop_factor_group ALTER COLUMN metric_id SET NOT NULL;
ALTER TABLE stop_factors.stop_factor_group
    ADD CONSTRAINT fk_stop_factor_metric FOREIGN KEY (metric_id) REFERENCES stop_factors.stop_factor_metric (id);
